-- Insert sample coupon batches
INSERT INTO coupon_batches (shop_id, batch_name, amount_per_coupon, expires_in_days, daily_limit, per_user_limit, start_time, end_time, is_active)
SELECT 
    s.id,
    'Student Discount Batch',
    CASE 
        WHEN s.name LIKE '%Pizza%' THEN 50.00
        WHEN s.name LIKE '%Tea%' THEN 10.00
        WHEN s.name LIKE '%Canteen%' THEN 25.00
        WHEN s.name LIKE '%South%' THEN 20.00
        WHEN s.name LIKE '%Juice%' THEN 15.00
        ELSE 30.00
    END,
    7, -- expires in 7 days
    100, -- 100 coupons per day
    2, -- 2 coupons per user
    '08:00:00', -- valid from 8 AM
    '22:00:00', -- valid till 10 PM
    true
FROM shops s;

